-- ============================================
-- LUMA — Thème 11 : MOYEN 3/3 x4 — Une rencontre qui devient amicale
-- ============================================


update scenarios set content = '{"characters": {"stranger": "un inconnu", "jamie": "Jamie"}, "start_node": "n1", "nodes": {"n1": {"speaker": "stranger", "text": "This line is taking forever, huh? At least the wait gives us something to complain about together.", "text_fr": "Cette file d''attente prend une éternité, hein ? Au moins l''attente nous donne quelque chose dont se plaindre ensemble.", "choices": [{"text": "Ha, true! Which stage are you most excited for today?", "text_fr": "Ha, vrai ! Quelle scène t''excite le plus aujourd''hui ?", "next": "n2"}, {"text": "Right? At least the weather''s nice while we wait.", "text_fr": "Hein ? Au moins il fait beau pendant qu''on attend.", "next": "n2b"}]}, "n2": {"speaker": "stranger", "text": "Honestly, the indie stage tonight — there''s a band I''ve been obsessed with for months.", "text_fr": "Honnêtement, la scène indie ce soir — il y a un groupe dont je suis obsédé depuis des mois.", "choices": [{"text": "No way, which band? I might know them.", "text_fr": "Sans blague, quel groupe ? Je les connais peut-être.", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "It really is! Perfect festival weather, honestly.", "text_fr": "C''est vraiment le cas ! Une météo de festival parfaite, honnêtement.", "choices": [{"text": "So, what brought you to this festival this year?", "text_fr": "Alors, qu''est-ce qui t''a amené à ce festival cette année ?", "next": "n3"}]}, "n3": {"speaker": "stranger", "text": "Luna Fields! Have you heard of them? Their new album is incredible.", "text_fr": "Luna Fields ! Tu les connais ? Leur nouvel album est incroyable.", "choices": [{"text": "Actually yes! I''ve had their song on repeat for weeks.", "text_fr": "En fait oui ! J''ai eu leur chanson en boucle pendant des semaines.", "next": "n4"}]}, "n3b": {"speaker": "stranger", "text": "Honestly, needed a break from work stress. This place always resets my mind.", "text_fr": "Honnêtement, j''avais besoin d''une pause du stress du travail. Cet endroit remet toujours mes idées en place.", "choices": [{"text": "I completely relate to that. Festivals are the best reset button.", "text_fr": "Je comprends totalement ça. Les festivals sont le meilleur bouton de réinitialisation.", "next": "n4"}]}, "n4": {"speaker": "stranger", "text": "No way, we have the same taste then! What else are you into music-wise?", "text_fr": "Sans blague, on a les mêmes goûts alors ! T''aimes quoi d''autre musicalement ?", "choices": [{"text": "Mostly indie and alternative, with some electronic mixed in.", "text_fr": "Surtout indie et alternatif, avec un peu d''électro mélangé.", "next": "n5"}]}, "n5": {"speaker": "stranger", "text": "We''re basically festival soulmates. I''m Jamie, by the way.", "text_fr": "On est basiquement des âmes sœurs de festival. Je m''appelle Jamie, au fait.", "choices": [{"text": "Nice to meet you, Jamie! Want to explore the festival together?", "text_fr": "Ravi de te rencontrer, Jamie ! Tu veux explorer le festival ensemble ?", "next": "n6"}, {"text": "Great to meet you! Maybe we''ll run into each other at the indie stage tonight.", "text_fr": "Super de te rencontrer ! On se croisera peut-être à la scène indie ce soir.", "next": "n6b"}]}, "n6": {"speaker": "jamie", "text": "I''d love that, honestly! It''s always better exploring with someone who gets it.", "text_fr": "J''adorerais ça, honnêtement ! C''est toujours mieux d''explorer avec quelqu''un qui comprend.", "choices": [{"text": "Perfect, let''s grab some food first and plan our day.", "text_fr": "Parfait, prenons d''abord à manger et planifions notre journée.", "next": "n7"}]}, "n6b": {"speaker": "jamie", "text": "Actually, why don''t we just stick together? More fun that way!", "text_fr": "En fait, pourquoi on resterait pas ensemble ? C''est plus fun comme ça !", "choices": [{"text": "I like that idea a lot. Let''s make a day of it.", "text_fr": "J''aime beaucoup cette idée. Faisons de cette journée un beau moment.", "next": "n7"}]}, "n7": {"speaker": "jamie", "text": "(Later, after hours of exploring together) This has honestly been the best festival day I''ve had in years.", "text_fr": "(Plus tard, après des heures à explorer ensemble) C''est honnêtement la meilleure journée de festival que j''ai eue depuis des années.", "choices": [{"text": "Same here! I''m really glad that line was so slow now.", "text_fr": "Pareil pour moi ! Je suis vraiment content que cette file ait été si lente maintenant.", "next": "n8"}]}, "n8": {"speaker": "jamie", "text": "Ha, me too! We should definitely exchange numbers, stay in touch after this.", "text_fr": "Ha, moi aussi ! On devrait définitivement échanger nos numéros, rester en contact après ça.", "choices": [{"text": "Absolutely, I''d love to stay friends beyond just today.", "text_fr": "Absolument, j''aimerais rester amis au-delà d''aujourd''hui.", "next": "end_friendship"}]}, "end_friendship": {"speaker": "jamie", "text": "This festival gave me way more than great music — it gave me a new friend.", "text_fr": "Ce festival m''a donné bien plus que de la super musique — il m''a donné un nouvel ami.", "end": true, "ending_label": "Une rencontre de file d''attente devenue amitié 🎶🤝"}}}'::jsonb, is_playable = true
where title = 'Une rencontre qui devient amicale'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
